package kr.mujoong.core.practice;

import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;
import java.time.Duration;
import java.util.*;
import kr.mujoong.core.practicegoal.FourElements;
import kr.mujoong.core.textai.*;
import org.junit.jupiter.api.*;

/** 실제 PG 선점/왕복과 서비스 운영 구성 선택 경계. HTTP 형식은 패키지 계약 시험에서 대조한다. */
@Tag("u10") class U10ScenarioApiIT {
    U10StructuredFixture f;
    @BeforeEach void open(){f=new U10StructuredFixture();}
    @AfterEach void close(){f.close();}
    @Test void configuredStructuredProviderBypassesLegacyGateway(){var s=f.legacy.service.generate(f.legacy.original());assertThat(s.scriptVersion()).isEqualTo("scenario-script.v1");verifyNoInteractions(f.legacy.ai);assertThat(f.legacy.repository.require(s.scenarioId()).scenario()).isEqualTo(s);}
    @Test void twoRejectedReviewsNeverPersistAnyScenario(){when(f.provider.review(any())).thenReturn(U10ScenarioGenerationTest.reject("AGE_MISMATCH"));assertThatThrownBy(()->f.legacy.service.generate(f.legacy.original())).isInstanceOf(kr.mujoong.core.common.error.CoreApiException.class);assertThat(f.legacy.db.jdbc().queryForObject("select count(*) from core.core_scenario where child_id=:id",new org.springframework.jdbc.core.namedparam.MapSqlParameterSource("id",f.legacy.child),Integer.class)).isZero();}
    @Test void deletedAccountAfterReviewPreventsWrite(){when(f.provider.review(any())).thenAnswer(c->{f.legacy.db.jdbc().update("update core.core_guardian set status='DELETION_REQUESTED' where id=:id",new org.springframework.jdbc.core.namedparam.MapSqlParameterSource("id",f.legacy.guardian));return U10ScenarioGenerationTest.approve();});f.legacy.error(()->f.legacy.service.generate(f.legacy.original()),kr.mujoong.contract.error.ErrorCode.ACCOUNT_DELETION_IN_PROGRESS);}
    @Test void endedSessionAfterReviewPreventsWrite(){when(f.provider.review(any())).thenAnswer(c->{f.legacy.current.set(new PracticeSessionContextPort.SessionContext(f.legacy.session,f.legacy.guardian,f.legacy.child,false,f.legacy.snapshot.goals()));return U10ScenarioGenerationTest.approve();});f.legacy.error(()->f.legacy.service.generate(f.legacy.original()),kr.mujoong.contract.error.ErrorCode.SESSION_NOT_ACTIVE);}
    @Test void preparedInitialLeaseCannotBeExtendedByGeneration(){var deadline=f.legacy.clock.now().plusSeconds(1);when(f.provider.generate(any())).thenAnswer(c->{f.legacy.clock.advance(Duration.ofSeconds(1));return f.generated("독서");});f.legacy.error(()->f.legacy.service.generatePrepared(f.legacy.original(),new ScenarioService.PreparedContext(deadline,()->f.legacy.snapshot)),kr.mujoong.contract.error.ErrorCode.SCENARIO_GEN_FAILED);verify(f.provider,never()).review(any());}
    @Test void candidateUsesFrozenFourElementsWithoutCatalog(){var context=new GoalContext(kr.mujoong.core.practicegoal.SavedGoalReader.SavedGoalView.Kind.CANDIDATE,"saved-ref",2,"잠깐 쉬자",new FourElements(f.legacy.opportunity,"PEER","그만두기","잠깐 쉬자"),"NONE",null,null);f.legacy.current.set(new PracticeSessionContextPort.SessionContext(f.legacy.session,f.legacy.guardian,f.legacy.child,true,List.of(new PracticeSessionContextPort.GoalSnapshot(f.legacy.goal,"candidate:saved-ref",2,"PEER",context))));clearInvocations(f.legacy.knowledge);var s=f.legacy.service.generate(f.legacy.original());assertThat(f.legacy.repository.require(s.scenarioId()).behaviorKey()).isEqualTo("candidate:saved-ref");verifyNoInteractions(f.legacy.knowledge);}
    @Test void supplierSemanticProjectionContainsNoIdentityReferences(){String candidate=UUID.randomUUID().toString();var context=new GoalContext(kr.mujoong.core.practicegoal.SavedGoalReader.SavedGoalView.Kind.CANDIDATE,candidate,2,"잠깐 쉬자",new FourElements(f.legacy.opportunity,"PEER","그만두기","잠깐 쉬자"),"NONE",null,null);f.legacy.current.set(new PracticeSessionContextPort.SessionContext(f.legacy.session,f.legacy.guardian,f.legacy.child,true,List.of(new PracticeSessionContextPort.GoalSnapshot(f.legacy.goal,"candidate:"+candidate,2,"PEER",context))));f.legacy.service.generate(f.legacy.original());var c=org.mockito.ArgumentCaptor.forClass(ScenarioScriptProvider.Call.class);verify(f.provider).generate(c.capture());verify(f.provider).review(c.capture());assertThat(c.getAllValues()).allSatisfy(call->assertThat(kr.mujoong.contract.json.JsonCodec.shared().write(call.input())).doesNotContain(candidate,f.legacy.goal.toString(),f.legacy.session.toString(),f.legacy.child.toString(),f.legacy.guardian.toString(),"candidateRef","sourceActivityId","judgmentCriteria"));}
    @Test void realControllerCarriesApprovedExtendedResponseOnExistingC10(){var json=kr.mujoong.contract.json.JsonCodec.shared();var controller=new kr.mujoong.core.practice.web.ScenarioInternalController(f.legacy.service,json);var response=controller.generate(json.write(f.legacy.original()));assertThat(response.getStatusCode().value()).isEqualTo(200);assertThat(kr.mujoong.core.web.support.WebFixtures.schemaErrors("practice-scenario.schema.json",json.write(response.getBody()))).isEmpty();assertThat(response.getBody().scriptVersion()).isEqualTo("scenario-script.v1");assertThat(response.getBody().selfReview().verdict()).isEqualTo("APPROVE");}
    @Test void consentWithdrawnWhileReviewingPreventsAnyWrite(){when(f.provider.review(any())).thenAnswer(c->{when(f.consent.check(any())).thenReturn(new kr.mujoong.core.consent.ConsentPolicyService.GateResult(false,kr.mujoong.core.consent.ConsentStatusRule.Status.NOT_GIVEN,null));return U10ScenarioGenerationTest.approve();});f.legacy.error(()->f.legacy.service.generate(f.legacy.original()),kr.mujoong.contract.error.ErrorCode.CONSENT_MISSING);assertNothingIssued();}
    @Test void sessionEndedBeforeFinalGuardianLockIsReadAgainInsideLock(){var count=new java.util.concurrent.atomic.AtomicInteger();doAnswer(c->{if(count.incrementAndGet()==2)f.legacy.current.set(new PracticeSessionContextPort.SessionContext(f.legacy.session,f.legacy.guardian,f.legacy.child,false,f.legacy.snapshot.goals()));return c.callRealMethod();}).when(f.accounts).requireActive(f.legacy.guardian,true);f.legacy.error(()->f.legacy.service.generate(f.legacy.original()),kr.mujoong.contract.error.ErrorCode.SESSION_NOT_ACTIVE);assertNothingIssued();}
    @Test void preparationCancelledBeforeFinalLockIsRecheckedInsideLock(){var cancelled=new java.util.concurrent.atomic.AtomicBoolean();var count=new java.util.concurrent.atomic.AtomicInteger();doAnswer(c->{if(count.incrementAndGet()==2)cancelled.set(true);return c.callRealMethod();}).when(f.accounts).requireActive(f.legacy.guardian,true);f.legacy.error(()->f.legacy.service.generatePrepared(f.legacy.original(),new ScenarioService.PreparedContext(f.legacy.clock.now().plusSeconds(15),()->{if(cancelled.get())throw kr.mujoong.core.common.error.CoreApiException.of(kr.mujoong.contract.error.ErrorCode.SERVICE_NOT_READY);return f.legacy.snapshot;})),kr.mujoong.contract.error.ErrorCode.SERVICE_NOT_READY);assertNothingIssued();}
    void assertNothingIssued(){assertThat(f.legacy.db.jdbc().queryForObject("select count(*) from core.core_scenario where child_id=:id",new org.springframework.jdbc.core.namedparam.MapSqlParameterSource("id",f.legacy.child),Integer.class)).isZero();}
    @Test void aliasInsideOpaqueReferenceKeepsStoredIdentityAndSanitizesOnlyContent(){
        when(f.privacy.require(f.legacy.guardian,f.legacy.child)).thenReturn(new ScenarioPrivacyContextPort.Context("abc"));
        var context=new GoalContext(kr.mujoong.core.practicegoal.SavedGoalReader.SavedGoalView.Kind.CANDIDATE,"abc-fixed",2,"abc 쉬자",new FourElements(f.legacy.opportunity,"PEER","그만두기","abc 쉬자"),"NONE",null,null);
        f.legacy.current.set(new PracticeSessionContextPort.SessionContext(f.legacy.session,f.legacy.guardian,f.legacy.child,true,List.of(new PracticeSessionContextPort.GoalSnapshot(f.legacy.goal,"candidate:abc-fixed",2,"PEER",context))));
        var generated=f.legacy.service.generate(f.legacy.original());
        assertThat(f.legacy.repository.require(generated.scenarioId()).goalContextJson()).contains("abc-fixed","아이 쉬자");
        var calls=org.mockito.ArgumentCaptor.forClass(ScenarioScriptProvider.Call.class);verify(f.provider).generate(calls.capture());verify(f.provider).review(calls.capture());
        assertThat(calls.getAllValues()).allSatisfy(call->assertThat(kr.mujoong.contract.json.JsonCodec.shared().write(call.input())).doesNotContain("abc-fixed","abc 쉬자"));
    }
    @Test void exhaustedContentIsPersistentlyFailedWithoutNewProviderCall(){when(f.provider.review(any())).thenReturn(U10ScenarioGenerationTest.reject("AGE_MISMATCH"));f.legacy.error(()->f.legacy.service.generate(f.legacy.original()),kr.mujoong.contract.error.ErrorCode.SCENARIO_GEN_FAILED);f.legacy.error(()->f.legacy.service.generate(f.legacy.original()),kr.mujoong.contract.error.ErrorCode.SCENARIO_GEN_FAILED);verify(f.provider,times(2)).generate(any());assertNothingIssued();}
    @Test void readyReplayStillChecksCurrentConsent(){f.legacy.service.generate(f.legacy.original());when(f.consent.check(any())).thenReturn(new kr.mujoong.core.consent.ConsentPolicyService.GateResult(false,kr.mujoong.core.consent.ConsentStatusRule.Status.NOT_GIVEN,null));f.legacy.error(()->f.legacy.service.generate(f.legacy.original()),kr.mujoong.contract.error.ErrorCode.CONSENT_MISSING);verify(f.provider).generate(any());}
    @Test void duplicateContentMissCanRetrySameKeyLikeLegacy(){f.legacy.service.generate(f.legacy.original());f.legacy.session=UUID.randomUUID();f.legacy.current.set(new PracticeSessionContextPort.SessionContext(f.legacy.session,f.legacy.guardian,f.legacy.child,true,f.legacy.snapshot.goals()));f.legacy.error(()->f.legacy.service.generate(f.legacy.original()),kr.mujoong.contract.error.ErrorCode.SCENARIO_GEN_FAILED);when(f.provider.generate(any())).thenReturn(f.generated("독서"));assertThat(f.legacy.service.generate(f.legacy.original()).scenarioText()).contains("독서");verify(f.provider,times(4)).generate(any());}
}
